-- UI-03: templates start with sample blocks so a new page is not empty. Existing pages keep their drafts.

update public.templates set default_config = '{"schemaVersion": 1, "template": "classic", "theme": {}, "layout": {"hero": {"blocks": ["b-hero"]}, "main": {"blocks": ["b-link-1", "b-link-2", "b-card-1"]}, "footer": {"blocks": ["b-foot"]}}, "profile": {"title": "Tên của bạn", "subtitle": "Giới thiệu ngắn về bạn", "socials": []}, "blocks": [{"id": "b-hero", "type": "banner", "text": "Chào mừng bạn ghé trang của mình", "subtext": "Sửa dòng này trong Nội dung trang"}, {"id": "b-link-1", "type": "link", "text": "Website của mình", "url": "https://example.com"}, {"id": "b-link-2", "type": "link", "text": "Liên hệ hợp tác", "url": "https://example.com/contact"}, {"id": "b-card-1", "type": "card", "text": "Bài viết nổi bật", "subtext": "Thay bằng nội dung bạn muốn giới thiệu"}, {"id": "b-foot", "type": "link", "text": "Theo dõi mình", "url": "https://example.com"}]}'::jsonb where key = 'classic';
update public.templates set default_config = '{"schemaVersion": 1, "template": "video-first", "theme": {}, "layout": {"hero": {"blocks": ["b-video"]}, "main": {"blocks": ["b-card-1", "b-card-2", "b-link-1"]}, "footer": {"blocks": ["b-foot"]}}, "profile": {"title": "Tên kênh", "subtitle": "Video mới mỗi tuần", "socials": []}, "blocks": [{"id": "b-video", "type": "video", "title": "Video mới nhất", "url": ""}, {"id": "b-card-1", "type": "card", "text": "Series nổi bật", "subtext": "Mô tả ngắn"}, {"id": "b-card-2", "type": "card", "text": "Hậu trường", "subtext": "Mô tả ngắn"}, {"id": "b-link-1", "type": "link", "text": "Kênh YouTube", "url": "https://youtube.com"}, {"id": "b-foot", "type": "link", "text": "Liên hệ hợp tác", "url": "https://example.com/contact"}]}'::jsonb where key = 'video-first';
update public.templates set default_config = '{"schemaVersion": 1, "template": "shop-grid", "theme": {}, "layout": {"hero": {"blocks": ["b-hero"]}, "main": {"blocks": ["b-shop", "b-card-1", "b-link-1"]}, "footer": {"blocks": ["b-foot"]}}, "profile": {"title": "Tên shop", "subtitle": "Sản phẩm mình chọn lọc", "socials": []}, "blocks": [{"id": "b-hero", "type": "banner", "text": "Ưu đãi tuần này", "subtext": "Nhập mã của bạn ở đây"}, {"id": "b-shop", "type": "shop", "title": "Đồ mình hay dùng"}, {"id": "b-card-1", "type": "card", "text": "Review mới", "subtext": "Mô tả ngắn"}, {"id": "b-link-1", "type": "link", "text": "Shop chính thức", "url": "https://example.com"}, {"id": "b-foot", "type": "link", "text": "Chat với mình", "url": "https://example.com"}]}'::jsonb where key = 'shop-grid';
